// report.json / report.md / report.html writers.
import fs from 'node:fs';
import path from 'node:path';
import { SEVERITIES, severityRank } from './rules.mjs';

export function sortFindings(findings) {
  return [...findings].sort((a, b) => severityRank(a.severity) - severityRank(b.severity)
    || a.page.localeCompare(b.page) || a.rule.localeCompare(b.rule));
}

export function summarize(findings) {
  const bySeverity = Object.fromEntries(SEVERITIES.map((s) => [s, 0]));
  const byCategory = {};
  for (const f of findings) {
    bySeverity[f.severity] = (bySeverity[f.severity] || 0) + 1;
    byCategory[f.category] = (byCategory[f.category] || 0) + 1;
  }
  const issues = findings.filter((f) => f.severity !== 'info').length;
  return { total: findings.length, issues, bySeverity, byCategory };
}

const mdEscape = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const code = (s) => '`' + String(s ?? '').replace(/`/g, "'") + '`';

export function toMarkdown(report) {
  const { meta, summary, pages, findings, safety } = report;
  const lines = [];
  lines.push(`# UI audit — ${meta.startURL}`, '');
  lines.push(`- Mode: **${meta.modeLabel}** · pages audited: **${pages.length}** · ${meta.stopped ? `stopped early (${meta.stopReason})` : 'completed'}`);
  lines.push(`- Started ${meta.startedAt} · took ${Math.round(meta.durationMs / 1000)}s · viewports ${meta.viewports.map((v) => `${v.width}×${v.height}`).join(', ')}`);
  lines.push(`- Allowed origins: ${meta.allowedOrigins.map(code).join(', ')}`);
  lines.push(`- Form submission: **${meta.submitPolicy}**`);
  lines.push('');
  lines.push('| Severity | Count |', '|---|---|');
  for (const s of SEVERITIES) if (summary.bySeverity[s]) lines.push(`| ${s} | ${summary.bySeverity[s]} |`);
  lines.push('');
  if (report.aiSummary) lines.push('## Summary', '', report.aiSummary, '');

  lines.push('## Pages', '', '| # | Page | Status | Issues |', '|---|---|---|---|');
  pages.forEach((p, i) => lines.push(`| ${i + 1} | ${mdEscape(p.url)} | ${p.status ?? '—'} | ${p.issues} |`));
  lines.push('');

  lines.push('## Findings', '');
  sortFindings(findings).forEach((f, i) => {
    lines.push(`### ${i + 1}. [${f.severity.toUpperCase()}] ${f.title}`, '');
    lines.push(`- **Page:** ${f.page}${f.viewport ? ` (${f.viewport})` : ''}`);
    if (f.alsoOn?.length) lines.push(`- **Also on:** ${f.alsoOn.slice(0, 8).join(', ')}${f.alsoOn.length > 8 ? ` (+${f.alsoOn.length - 8} more)` : ''}`);
    if (f.selector) lines.push(`- **Element:** ${code(f.selector)}${f.locator ? ` — ${code(f.locator)}` : ''}`);
    lines.push(`- **Rule:** ${code(f.rule)} (${f.category})${f.helpUrl ? ` — ${f.helpUrl}` : ''}`);
    if (f.evidence) lines.push(`- **Evidence:** ${mdEscape(f.evidence)}`);
    if (f.expected) lines.push(`- **Expected:** ${mdEscape(f.expected)}`);
    if (f.actual) lines.push(`- **Actual:** ${mdEscape(f.actual)}`);
    if (f.steps?.length) {
      lines.push('- **Steps to reproduce:**');
      f.steps.forEach((s, k) => lines.push(`  ${k + 1}. ${s}`));
    }
    if (f.fix) lines.push(`- **Suggested fix:** ${mdEscape(f.fix)}`);
    if (f.screenshot) lines.push('', `![screenshot](${f.screenshot})`);
    lines.push('');
  });

  lines.push('## Safety log', '');
  lines.push(`- Requests blocked (writes while submission was off, or navigations outside allowed origins): ${safety.blocked.length}`);
  for (const b of safety.blocked.slice(0, 30)) lines.push(`  - ${b.reason}: ${code(`${b.method} ${b.url}`)}`);
  lines.push(`- Elements not clicked because they look destructive or financial: ${safety.skippedDangerous.length}`);
  for (const d of safety.skippedDangerous.slice(0, 30)) lines.push(`  - ${code(d.selector)} "${mdEscape(d.text)}" on ${d.page}`);
  lines.push(`- Links outside the allowed origins (not visited): ${safety.externalLinks.length}`);
  lines.push(`- Sensitive fields left empty: ${safety.sensitiveFields.length}`);
  lines.push('');
  lines.push('_Generated by SparkV UI audit (Playwright + axe-core). Test data is synthetic (example.com addresses, fictional phone numbers)._');
  return lines.join('\n');
}

const h = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

export function toHTML(report) {
  const { meta, summary, pages, findings } = report;
  const sevColor = { critical: '#ff375f', high: '#ff9f0a', medium: '#ffd60a', low: '#64d2ff', info: '#8e8e93' };
  const cards = sortFindings(findings).map((f, i) => `
    <article class="f">
      <header><span class="sev" style="background:${sevColor[f.severity]}">${h(f.severity)}</span>
        <h3>${i + 1}. ${h(f.title)}</h3></header>
      <dl>
        <dt>Page</dt><dd><a href="${h(f.page)}">${h(f.page)}</a>${f.viewport ? ` · ${h(f.viewport)}` : ''}</dd>
        ${f.alsoOn?.length ? `<dt>Also on</dt><dd>${f.alsoOn.slice(0, 8).map(h).join('<br>')}</dd>` : ''}
        ${f.selector ? `<dt>Element</dt><dd><code>${h(f.selector)}</code>${f.locator ? `<br><code>${h(f.locator)}</code>` : ''}</dd>` : ''}
        <dt>Rule</dt><dd><code>${h(f.rule)}</code> · ${h(f.category)}${f.helpUrl ? ` · <a href="${h(f.helpUrl)}">docs</a>` : ''}</dd>
        ${f.evidence ? `<dt>Evidence</dt><dd>${h(f.evidence)}</dd>` : ''}
        ${f.expected ? `<dt>Expected</dt><dd>${h(f.expected)}</dd>` : ''}
        ${f.actual ? `<dt>Actual</dt><dd>${h(f.actual)}</dd>` : ''}
        ${f.steps?.length ? `<dt>Repro</dt><dd><ol>${f.steps.map((s) => `<li>${h(s)}</li>`).join('')}</ol></dd>` : ''}
        ${f.fix ? `<dt>Fix</dt><dd>${h(f.fix)}</dd>` : ''}
      </dl>
      ${f.screenshot ? `<a href="${h(f.screenshot)}"><img loading="lazy" src="${h(f.screenshot)}" alt="Screenshot for finding ${i + 1}"></a>` : ''}
    </article>`).join('\n');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>UI audit report</title>
<style>
:root{color-scheme:dark;--bg:#111214;--card:#1c1d21;--text:#f2f2f4;--muted:#a1a1aa;--line:#2c2d33}
body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 -apple-system,BlinkMacSystemFont,"SF Pro Text",system-ui,sans-serif}
main{max-width:980px;margin:0 auto;padding:24px 16px 64px}
h1{font-size:22px;margin:0 0 4px}h3{font-size:15px;margin:0}
.meta{color:var(--muted);margin:0 0 16px}
.counts{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 24px}.counts span{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:4px 10px}
.f{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px;margin:12px 0}
.f header{display:flex;gap:10px;align-items:center;margin-bottom:8px}
.sev{color:#000;border-radius:6px;padding:1px 8px;font-size:12px;font-weight:600;text-transform:uppercase}
dl{display:grid;grid-template-columns:90px 1fr;gap:4px 12px;margin:0}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}
code{background:#000;border-radius:4px;padding:0 4px;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}
img{max-width:100%;border-radius:8px;margin-top:10px;border:1px solid var(--line)}a{color:#64d2ff}
table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid var(--line);padding:4px 6px;text-align:left;overflow-wrap:anywhere}
</style></head><body><main>
<h1>UI audit</h1>
<p class="meta">${h(meta.startURL)} · ${h(meta.modeLabel)} · ${pages.length} page(s) · ${h(meta.startedAt)} · submission ${h(meta.submitPolicy)}${meta.stopped ? ` · stopped: ${h(meta.stopReason)}` : ''}</p>
<div class="counts">${SEVERITIES.filter((s) => summary.bySeverity[s]).map((s) => `<span>${s}: <b>${summary.bySeverity[s]}</b></span>`).join('')}</div>
${report.aiSummary ? `<h2>Summary</h2><p>${h(report.aiSummary).replace(/\n/g, '<br>')}</p>` : ''}
<h2>Pages</h2><table><tr><th>#</th><th>URL</th><th>Status</th><th>Issues</th></tr>
${pages.map((p, i) => `<tr><td>${i + 1}</td><td>${h(p.url)}</td><td>${h(p.status ?? '—')}</td><td>${p.issues}</td></tr>`).join('')}</table>
<h2>Findings</h2>${cards || '<p>No findings.</p>'}
</main></body></html>`;
}

export function writeReport(outDir, report) {
  fs.mkdirSync(outDir, { recursive: true });
  const jsonPath = path.join(outDir, 'report.json');
  const mdPath = path.join(outDir, 'report.md');
  const htmlPath = path.join(outDir, 'report.html');
  fs.writeFileSync(jsonPath, JSON.stringify(report, null, 2));
  fs.writeFileSync(mdPath, toMarkdown(report));
  fs.writeFileSync(htmlPath, toHTML(report));
  return { jsonPath, mdPath, htmlPath };
}
